from openpyxl import Workbook

def make(path, rows):
    wb = Workbook()
    ws = wb.active
    ws.title = "学生名单"
    ws.append(["学号", "姓名", "性别"])
    for r in rows:
        ws.append(list(r))
    for row in ws.iter_rows(min_row=2):
        for c in row:
            c.number_format = "@"   # 文本格式，防学号被转成科学计数
    wb.save(path)

